import json

questions = []

def add_q(topic, difficulty, companies, question, options, answer_idx, explanation):
    questions.append({
        "id": len(questions) + 1,
        "difficulty": difficulty,
        "topic": topic,
        "companyPattern": companies,
        "question": question,
        "options": options,
        "answer": answer_idx,
        "explanation": explanation
    })

# Define 250 Questions across 13 units

# --- UNIT 1: Introduction to OS (18 Qs) ---
add_q("Introduction to OS", "Easy", ["TCS", "Infosys", "Wipro"], "Which of the following is the primary purpose of an Operating System?", ["To provide a user interface for web browsing", "To manage hardware resources and provide an environment for running applications", "To execute database queries efficiently", "To compile high-level programming code into machine instructions"], 1, "The primary goal of an Operating System is to manage computer hardware resources (CPU, memory, disk, I/O) efficiently and provide an abstraction layer for application programs to execute smoothly.")
add_q("Introduction to OS", "Easy", ["Accenture", "Capgemini", "Deloitte"], "In which type of operating system are jobs submitted in batches and processed without user interaction?", ["Time-Sharing Operating System", "Real-Time Operating System", "Batch Operating System", "Distributed Operating System"], 2, "Batch Operating Systems collect jobs of similar requirements into batches and execute them sequentially without direct user interaction during execution.")
add_q("Introduction to OS", "Medium", ["Amazon", "Microsoft", "Oracle"], "What is the main difference between User Mode and Kernel Mode in modern CPUs?", ["User Mode allows direct hardware execution, while Kernel Mode uses software emulation.", "Kernel Mode has execution access to all CPU instructions and memory, whereas User Mode is restricted.", "User Mode runs faster because it bypasses security checks.", "Kernel Mode can only execute single-threaded tasks."], 1, "Kernel Mode operates at Dual-Mode CPU ring 0 with full access to hardware privileges and memory space. User Mode (ring 3) prevents user applications from executing privileged instructions directly.")
add_q("Introduction to OS", "Easy", ["TCS", "HCL", "Tech Mahindra"], "What component of an operating system directly interacts with the computer hardware?", ["Shell", "Kernel", "Command Prompt", "Compiler"], 1, "The Kernel is the core component of an OS that sits between software applications and physical hardware, directly handling memory, process, device, and file management.")
add_q("Introduction to OS", "Medium", ["Qualcomm", "Intel", "Samsung"], "During the system booting process, which of the following is executed first by the CPU?", ["Operating System Kernel", "Init / Systemd Process", "BIOS / UEFI Firmware", "Bootloader (GRUB)"], 2, "When power is applied, the CPU starts executing BIOS/UEFI firmware from ROM. BIOS performs POST and loads the Bootloader, which then loads the OS Kernel into main memory.")
add_q("Introduction to OS", "Easy", ["IBM", "LTIMindtree", "Infosys"], "Which OS architecture bundles all operating system services into a single monolithic binary running in kernel space?", ["Microkernel Architecture", "Monolithic Kernel Architecture", "Exokernel Architecture", "Hybrid Architecture"], 1, "A Monolithic Kernel executes all core OS subsystems in a unified privileged kernel address space. Microkernels keep only minimal core services in kernel space.")
add_q("Introduction to OS", "Medium", ["Google", "Meta", "Amazon"], "What happens when a user program attempts to execute a privileged instruction while running in User Mode?", ["The instruction is executed normally with elevated rights.", "The CPU generates a hardware trap/exception, switching execution to Kernel Mode.", "The CPU halts the entire computer system immediately.", "The instruction is ignored and skipped without any error."], 1, "Executing a privileged instruction while in User Mode triggers a hardware trap. The CPU transitions control to the OS kernel trap handler, which handles or terminates the process.")
add_q("Introduction to OS", "Hard", ["Nvidia", "Qualcomm", "Cisco"], "Which requirement is MOST critical for a Hard Real-Time Operating System (RTOS)?", ["Maximizing overall system throughput", "Guaranteeing that tasks complete strictly before their specified deadlines", "Providing an aesthetic graphical user interface", "Supporting maximum concurrent virtual memory capacity"], 1, "In a Hard Real-Time OS, missing a deadline constitutes a total system failure. Deterministic hard deadline enforcement is paramount.")
add_q("Introduction to OS", "Easy", ["TCS", "Wipro", "Cognizant"], "Which of the following is an example of a Command Line Interface (CLI) Shell in Unix/Linux?", ["GNOME", "Bash", "KDE Plasma", "X11"], 1, "Bash (Bourne Again Shell) is a CLI shell interpreter. GNOME and KDE Plasma are Graphical User Interfaces.")
add_q("Introduction to OS", "Medium", ["Deloitte", "Capgemini", "Accenture"], "Spooling (Simultaneous Peripheral Operations On-Line) was primarily introduced to solve which operational problem?", ["Slow speed differences between CPU and slow I/O devices like printers", "Memory fragmentation in virtual memory systems", "Deadlock occurrence in concurrent processes", "CPU register overflow during context switching"], 0, "Spooling uses disk storage as a buffer queue for slow peripheral devices, preventing the fast CPU from waiting synchronously for slow physical devices.")
add_q("Introduction to OS", "Medium", ["Goldman Sachs", "JPMorgan"], "Which system interrupt is routinely generated by a hardware timer to enable time-sharing process context switches?", ["I/O Completion Interrupt", "Page Fault Interrupt", "Timer Interrupt", "Software Trap"], 2, "A hardware timer periodically fires a Timer Interrupt to preempt the currently running process and pass control to the OS short-term scheduler.")
add_q("Introduction to OS", "Easy", ["Infosys", "TCS", "Zoho"], "Which OS concept allows multiple program instances to reside in main memory simultaneously, keeping the CPU active by switching to another job when one is waiting for I/O?", ["Multiprogramming", "Single-user mode", "Serial processing", "Batch queuing"], 0, "Multiprogramming holds multiple jobs in memory. When the active job blocks on I/O, the OS switches the CPU to another memory-resident job.")
add_q("Introduction to OS", "Hard", ["Microsoft", "Adobe", "Google"], "Consider an OS microkernel design. What is the primary performance trade-off compared to a monolithic kernel?", ["Microkernels consume significantly more disk space.", "Frequent Inter-Process Communication (IPC) and context switching between user-space services reduce performance speed.", "Microkernels cannot support multi-core CPU architectures.", "Microkernels lack support for file systems entirely."], 1, "Microkernels run services in user space. IPC messages and context switches between services introduce performance overhead compared to monolithic function calls.")
add_q("Introduction to OS", "Medium", ["VMware", "Oracle"], "What is the role of the Dual-Mode operation bit in modern processor registers?", ["To switch between 32-bit and 64-bit address space", "To differentiate between User Mode (mode bit = 1) and Kernel Mode (mode bit = 0)", "To enable or disable floating-point calculations", "To switch between Wi-Fi and Ethernet communication modes"], 1, "The CPU mode bit indicates execution privilege: mode bit 0 for Kernel Mode (privileged) and 1 for User Mode (unprivileged).")
add_q("Introduction to OS", "Easy", ["HCL", "Wipro", "Tech Mahindra"], "Which of the following is NOT a core responsibility of an Operating System?", ["Process Scheduling", "Memory Allocation", "Source Code Compilation", "File System Management"], 2, "Source code compilation is performed by compilers, which are application software. Process scheduling, memory allocation, and file systems are OS core responsibilities.")
add_q("Introduction to OS", "Medium", ["ServiceNow", "SAP"], "Which component loads the operating system kernel into RAM from persistent storage during system startup?", ["Compiler", "Bootloader", "Device Manager", "Assembler"], 1, "The Bootloader (e.g. GRUB, Windows Boot Manager) is loaded by BIOS/UEFI to transfer control and load the OS kernel into RAM.")
add_q("Introduction to OS", "Hard", ["Amazon", "Qualcomm"], "Assertion (A): Microkernels are safer and more stable than Monolithic kernels.\nReason (R): In a Microkernel architecture, driver crashes run in user space and do not crash the entire operating system.", ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is NOT the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], 0, "Because microkernel device drivers execute in isolated user spaces, a driver crash does not corrupt kernel space or crash the whole operating system.")
add_q("Introduction to OS", "Easy", ["TCS", "Cognizant"], "Embedded Operating Systems are typically found in which of the following devices?", ["Mainframe Supercomputers", "Washing machines, Smartwatches, and Automotive ECUs", "Cloud Data Center Server Clusters", "Desktop Gaming Rigs"], 1, "Embedded OSs (e.g. FreeRTOS, VxWorks) are tailored for low-power, dedicated hardware devices like home appliances and smart wearables.")

# --- UNIT 2: Process Management (20 Qs) ---
add_q("Process Management", "Easy", ["TCS", "Infosys", "Wipro"], "Which of the following best describes the fundamental difference between a Program and a Process?", ["A program is active in RAM; a process is passive on disk.", "A program is a passive collection of instructions stored on disk; a process is an active instance of a program being executed in memory.", "A program can spawn processes, but a process cannot execute programs.", "Programs use system calls, while processes only use register calls."], 1, "A program is a passive executable file on disk. A process is an active entity executing in memory with registers, stack, program counter, and heap.")
add_q("Process Management", "Easy", ["Accenture", "Capgemini", "Deloitte"], "Which Process State transition occurs when a running process requires I/O input from a user or disk?", ["Running -> Ready", "Running -> Blocked / Waiting", "Blocked -> Running", "Ready -> Terminated"], 1, "When a running process issues an I/O request, it transitions from Running to Blocked/Waiting state until the I/O operation completes.")
add_q("Process Management", "Medium", ["Amazon", "Microsoft", "Google"], "What information is stored inside the Process Control Block (PCB)?", ["Only the source code of the program", "Process ID, Process State, Program Counter, CPU Registers, Memory Allocation Info, and Open File Descriptors", "Hardware BIOS driver binaries", "User network bandwidth configurations"], 1, "The PCB stores essential process execution context including PID, state, program counter, register states, memory limits, and file pointers.")
add_q("Process Management", "Medium", ["Oracle", "Qualcomm", "Intel"], "What occurs during a CPU Context Switch?", ["The CPU reboots to refresh registers.", "The OS saves the execution context of the active process into its PCB and restores the context of the newly scheduled process from its PCB.", "The kernel translates virtual memory addresses to disk offsets.", "All running threads are terminated and recreated."], 1, "During a context switch, the OS kernel saves CPU registers of the running process to its PCB and loads saved state from the newly chosen process PCB.")
add_q("Process Management", "Easy", ["IBM", "LTIMindtree", "TCS"], "Which process scheduler selects processes from mass-storage devices (disk) and loads them into memory for execution?", ["Short-Term Scheduler", "Medium-Term Scheduler", "Long-Term Scheduler", "Dispatch Scheduler"], 2, "The Long-Term Scheduler (Job Scheduler) controls the degree of multiprogramming by selecting jobs from disk storage and loading them into main memory.")
add_q("Process Management", "Medium", ["Goldman Sachs", "JPMorgan"], "What is a Zombie Process in Unix/Linux OS?", ["A process that runs endlessly without consuming CPU cycles", "A process that has completed execution, but its exit status has not yet been read by its parent process via wait()", "A process whose parent terminated without waiting for it", "A process executing with negative root privileges"], 1, "A Zombie process has finished execution and freed memory, but its entry remains in the kernel process table until its parent calls wait() to read its termination code.")
add_q("Process Management", "Medium", ["Zoho", "Paytm", "Flipkart"], "What is an Orphan Process in Unix/Linux OS, and how is it handled by the operating system?", ["A process whose parent terminated before it; it is automatically adopted by the init process (PID 1).", "A process that has no memory allocated; it is terminated immediately.", "A thread that has lost its thread group ID.", "A process executing without an assigned CPU core."], 0, "When a parent process terminates before its child process finishes, the child becomes an Orphan and is re-parented to init (PID 1).")
add_q("Process Management", "Hard", ["Meta", "Amazon", "Microsoft"], "In Unix-like systems, what is the exact return value of the fork() system call in the Parent process and Child process, respectively?", ["Parent gets 0; Child gets PID of parent.", "Parent gets PID of child; Child gets 0.", "Parent gets 1; Child gets 0.", "Parent gets PID of child; Child gets PID of parent."], 1, "Upon successful execution of fork(), 0 is returned in the newly created child process, and the child process ID (PID) is returned in the parent process.")
add_q("Process Management", "Medium", ["Adobe", "Salesforce", "Atlassian"], "How does the exec() family of system calls differ from the fork() system call?", ["fork() terminates a process, while exec() creates a child.", "fork() creates a duplicate copy of the existing process; exec() replaces the current process address space with a new program executable.", "fork() operates in user space; exec() operates exclusively in hardware ROM.", "exec() allocates new PID while fork() reuses parent PID."], 1, "fork() clones the calling process. exec() overwrites the address space, stack, heap, and code of the calling process with a new executable program.")
add_q("Process Management", "Hard", ["Nvidia", "Google", "Qualcomm"], "Consider the C code snippet: `fork(); fork(); fork();` Assuming all fork() calls succeed, how many TOTAL processes exist after execution?", ["3", "6", "8", "7"], 2, "Each fork doubling process count gives 2^3 = 8 processes (1 original parent + 7 child processes).")
add_q("Process Management", "Medium", ["Samsung", "Intel", "Cisco"], "What is the main role of the Medium-Term Scheduler in operating systems?", ["Assigning CPU to ready processes every few milliseconds", "Swapping processes between main memory and secondary disk space to manage memory pressure", "Loading programs from disk into main memory initially", "Handling network socket packets"], 1, "The Medium-Term Scheduler manages swapping between main memory and disk swap space to regulate RAM utilization.")
add_q("Process Management", "Easy", ["TCS", "Wipro", "Infosys"], "Which state is a process in immediately after it is created by the fork() system call?", ["Running", "Ready", "Waiting", "Terminated"], 1, "After creation, a new process enters the Ready state queue waiting to be assigned a CPU core by the short-term scheduler.")
add_q("Process Management", "Hard", ["Walmart Global Tech", "PayPal"], "Consider the code: `if (fork() == 0) { printf(\"Child\\n\"); } else { wait(NULL); printf(\"Parent\\n\"); }` What is the guaranteed output order?", ["Parent followed by Child", "Child followed by Parent", "Child and Parent printed simultaneously", "Unpredictable output order"], 1, "In the parent process, wait(NULL) forces the parent to suspend until the child process completes execution. Thus 'Child' prints before 'Parent'.")
add_q("Process Management", "Medium", ["ServiceNow", "LTIMindtree"], "What is the CPU bound vs I/O bound process ratio's impact on system performance?", ["A system with only CPU-bound processes has higher I/O queue utilization.", "An optimal balance of CPU-bound and I/O-bound processes maximizes overall CPU and device utilization.", "I/O-bound processes should never be admitted.", "CPU-bound processes execute entirely in kernel mode."], 1, "A balanced mix of CPU-bound and I/O-bound jobs maximizes overall resource utilization across processor cores and peripheral controllers.")
add_q("Process Management", "Easy", ["HCL", "Tech Mahindra"], "Which section of a process's memory layout stores dynamically allocated memory created at runtime via malloc()?", ["Text Segment", "Stack Segment", "Heap Segment", "Data Segment"], 2, "The Heap segment holds dynamically allocated memory assigned at runtime. Stack holds local variables and function calls.")
add_q("Process Management", "Hard", ["Google", "Microsoft"], "Assertion (A): Cascading Termination occurs in some operating systems when a parent process terminates.\nReason (R): If a parent process is terminated, all its child processes must also be terminated by the OS.", ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is NOT the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."], 0, "Cascading termination refers to the policy where the death of a parent process causes the automatic termination of all its descendant child processes by the OS.")
add_q("Process Management", "Medium", ["Accenture", "Cognizant"], "What is context switch latency overhead mainly influenced by?", ["Disk seek rotational delay", "Saving and restoring CPU register state, flushing/invalidating TLB caches, and switching memory page tables", "Network latency", "Keyboard interrupt processing"], 1, "Context switch overhead includes saving hardware CPU registers to PCB, reloading new registers, changing page directories, and invalidating CPU caches.")
add_q("Process Management", "Easy", ["Infosys", "TCS"], "Which process state transition is IMPOSSIBLE under standard OS state models?", ["Ready -> Running", "Running -> Blocked", "Blocked -> Running", "Blocked -> Ready"], 2, "A Blocked process cannot move directly to Running. When I/O completes, it moves to Ready state, waiting for the short-term CPU scheduler.")
add_q("Process Management", "Medium", ["VMware", "Cisco"], "What is the function of the Program Counter (PC) register maintained within a process context?", ["Counts total running processes", "Holds the memory address of the next instruction to be executed by the CPU for that process", "Tracks memory bytes allocated on heap", "Stores process priority score"], 1, "The Program Counter points to the instruction memory address that the CPU will fetch next for that specific process.")
add_q("Process Management", "Hard", ["Amazon", "Qualcomm"], "How does Copy-On-Write (COW) optimize the performance of the fork() system call?", ["It compresses parent memory before spawning child.", "It initially shares parent memory pages with the child read-only, copying a page only when either process attempts to modify it.", "It writes child data directly to disk swap space.", "It delays child creation until exec() is called."], 1, "Copy-On-Write avoids duplicating physical memory during fork(). Parent and child share read-only pages, creating a private copy of a page only when modified.")

print("Base setup saved. Initial length:", len(questions))
